    "footer_desc": "कृत्रिम बुद्धिमत्ता द्वारा किसानों का सशक्तिकरण। आने वाले कल के लिए समृद्ध और स्मार्ट कृषि का निर्माण।",
    "footer_copyright": "© 2026 खेत एआई. सर्वाधिकार सुरक्षित। किसानों के लिए समर्पित।",
    "faq_badge": "अक्सर पूछे जाने वाले प्रश्न",
    "faq_title": "आपको जो कुछ जानने की आवश्यकता है",
    "faq_desc": "खेत एआई (Khet AI) के कंप्यूटर विज़न, मौसम टेलीमेट्री और कृषि संबंधी सामान्य प्रश्नों के उत्तर प्राप्त करें।",
    "faq_q1": "फसल रोग पहचान कैसे काम करती है?",
    "faq_a1": "हमारा कंप्यूटर विज़न इंजन 50 लाख से अधिक पत्तियों के नमूनों पर प्रशिक्षित डीप न्यूरल नेटवर्क (ResNet एवं विज़न ट्रांसफॉर्मर) द्वारा संचालित है। जब आप पत्ती का फोटो अपलोड या कैप्चर करते हैं, तो मॉडल पत्तियों के रंग, धब्बों के आकार और फफूंद पैटर्न की जांच करके 95% तक सटीकता के साथ रोग पहचानता है और तत्काल जैविक व रासायनिक उपचार बताता है।",
    "faq_q2": "क्या मौसम का डेटा रीयल-टाइम है?",
    "faq_a2": "हाँ! खेत एआई इसरो (ISRO), सेंटिनल और नोआ (NOAA) उपग्रहों के साथ 1 वर्ग किमी के माइक्रो-डॉपलर रडार स्टेशनों से रीयल-टाइम डेटा सिंक करता है। यह डेटा हर 15 मिनट में अपडेट होता है ताकि अचानक बारिश, छिड़काव हेतु हवा की दिशा और कवक बीजाणु बनने वाली नमी की सटीक चेतावनी मिल सके।",
    "faq_q3": "क्या मैं नई फसलें उगा सकता हूँ?",
    "faq_a3": "बिल्कुल। हमारा एआई फसल सिफारिश इंजन आपकी मिट्टी के प्रकार (जलोढ़, काली, लाल, बलुई), उपलब्ध सिंचाई स्रोतों, मौसमी परिस्थितियों और बजट का मूल्यांकन करके उच्च लाभ देने वाली वैकल्पिक फसलों की सिफारिश करता है, जिसमें प्रति एकड़ अनुमानित लाभ मार्जिन भी शामिल है।",
    "faq_q4": "भविष्यवाणियां कितनी सटीक हैं?",
    "faq_a4": "राज्य कृषि विश्वविद्यालयों में किए गए फील्ड परीक्षणों में खेत एआई ने 100 से अधिक प्रमुख फसल रोगों में 95.8% निदान सटीकता हासिल की है। मंडी भाव के पूर्वानुमान बहु-वर्षीय एपीएमसी मूल्य मॉडलों के आधार पर 7 से 14 दिनों की अवधि में 89% सटीक रहते हैं।",
    "faq_q5": "क्या यह मंच किसानों के लिए मुफ्त है?",
    "faq_a5": "हाँ! खेत एआई की बुनियादी सुविधाएं—जैसे फसल रोग निदान, हाइपरलोकल मौसम परामर्श, फसल ज्ञान मार्गदर्शिका और मंडी भाव ट्रैकर—व्यक्तिगत किसानों के लिए पूरी तरह से मुफ्त हैं।",
    "disease_search_title": "फसल रोग दर्ज करें या बोलकर बताएं:",
