    "about_card1_desc": "मिट्टी परीक्षण, बीज चयन और बुवाई कार्यक्रम से लेकर कटाई और मंडी व्यापार तक निरंतर मार्गदर्शन।",
    "about_card2_title": "उपग्रह और ड्रोन एआई",
    "about_card2_desc": "उच्च-रिज़ॉल्यूशन मल्टी-स्पेक्ट्रल उपग्रह इमेजरी और माइक्रॉक्लाइमेट टेलीमेट्री सीधे आपके खेत से जुड़ी है।",
    "about_card3_title": "त्वरित रोग निदान",
    "about_card3_desc": "कंप्यूटर विज़न न्यूरल नेटवर्क 100 से अधिक पत्ती रोगों का 2 सेकंड के भीतर 95% सटीकता से निदान करते हैं।",
    "about_card4_title": "किसान-हितैषी और क्षेत्रीय",
    "about_card4_desc": "हिंदी, पंजाबी, मराठी, तेलुगु और अंग्रेजी में उपलब्ध आवाज़-सक्षम संवादात्मक सहायक।",
    "about_trad_badge": "पारंपरिक खेती",
    "about_trad_title": "अनुमान और बेमौसम जोखिमों पर निर्भरता",
    "about_trad_p1": "शुरुआती फफूंद बीजाणुओं का पता न चलने से भारी फसल नुकसान",
    "about_trad_p2": "अत्यधिक उर्वरक के उपयोग से मिट्टी की उर्वरता में गिरावट",
    "about_trad_p3": "मंडी भाव की जानकारी न होने से औने-पौने दामों पर फसल बेचना",
    "about_khet_badge": "खेत एआई स्मार्ट कृषि के साथ",
    "about_khet_title": "डेटा-आधारित सटीकता और अधिकतम मुनाफा",
    "about_khet_p1": "जैविक और रासायनिक खुराक के साथ तत्काल पत्ती रोग पहचान",
    "about_khet_p2": "मिट्टी-अनुकूल एनपीके सिफारिशें जो खाद की लागत 28% तक कम करती हैं",
    "about_khet_p3": "एआई मंडी भाव भविष्यवाणी जो पीक सीजन दरों पर बिक्री सुनिश्चित करती है",
    "features_badge": "मंच की व्यापक विशेषताएं",
    "features_title": "आधुनिक किसानों की हर जरूरत, एक ही ऐप में",
    "features_desc": "अत्याधुनिक कंप्यूटर विज़न, डीप लर्निंग एल्गोरिदम और वास्तविक समय कृषि टेलीमेट्री, विशेष रूप से उच्च उपज के लिए तैयार।",
    "feat1_title": "एआई फसल रोग पहचान",
    "feat1_desc": "पत्ती का फोटो अपलोड करें और सटीक जैविक व रासायनिक उपचार सलाह के साथ तुरंत रोग पहचानें।",
    "feat1_btn": "पत्ती स्कैनर आज़माएं",
    "feat2_title": "स्मार्ट मौसम पूर्वानुमान",
    "feat2_desc": "तापमान, बारिश, नमी, हवा की गति देखें और कीटनाशक छिड़काव व सिंचाई के लिए कृषि सलाह प्राप्त करें।",
    "feat2_btn": "7-दिवसीय रडार देखें",
