    "feat4_title": "फसल ज्ञान केंद्र",
    "feat4_desc": "जीवन चक्र, सर्वोत्तम मौसम, मिट्टी का प्रकार, पानी की आवश्यकता, खाद कार्यक्रम और मंडी भाव सीखें।",
    "feat4_btn": "ज्ञानकोष देखें",
    "feat5_title": "मंडी मूल्य विश्लेषण",
    "feat5_desc": "लाइव मंडी भाव, साप्ताहिक मूल्य रुझान और संकटपूर्ण बिक्री से बचने के लिए एआई बिक्री सलाह देखें।",
