    "feat6_title": "स्मार्ट सिंचाई योजना",
    "feat6_desc": "बुद्धिमान सिंचाई योजना, वाष्पोत्सर्जन सूचकांक और नमी सेंसर स्वचालन द्वारा पानी का इष्टतम उपयोग करें।",
    "feat6_btn": "सिंचाई योजना",
    "feat7_title": "एआई कृषि सहायक",
    "feat7_desc": "खेती से जुड़े कोई भी सवाल पूछें और अपनी स्थानीय भाषा में 24/7 तत्काल एआई उत्तर प्राप्त करें।",
