    "feat8_desc": "सब्सिडी, फसल बीमा, सोलर पंप और कृषि सहायता योजनाओं की पात्रता तुरंत जांचें।",
    "feat8_btn": "सब्सिडी पात्रता जांचें",
    "how_badge": "सरल 4-चरणीय प्रक्रिया",
    "how_title": "खेत एआई कैसे काम करता है",
    "how_desc": "केवल चार आसान चरणों में कृषि डेटा को व्यावहारिक सिफारिशों में बदलें।",
