    "faq_q1": "रोग निदान कसे कार्य करते?",
    "faq_a1": "आमचे कॉम्प्युटर व्हिजन इंजिन ५० लाखांहून अधिक पानांच्या नमुन्यांवर प्रशिक्षित डीप न्यूरल नेटवर्कद्वारे चालते. जेव्हा तुम्ही फोटो अपलोड करता, तेव्हा मॉडेल ९५% अचूकतेसह रोगाचे वर्गीकरण करते आणि त्वरित सेंद्रिय व रासायनिक उपचार सुचवते.",
