    "feat4_title": "फसल ज्ञान केंद्र",
    "feat4_desc": "जीवन चक्र, सर्वोत्तम मौसम, मिट्टी का प्रकार, पानी की आवश्यकता, खाद कार्यक्रम और मंडी भाव सीखें।",
