    "faq_q1": "રોગ નિદાન કેવી રીતે કાર્ય કરે છે?",
    "faq_a1": "અમારું કોમ્પ્યુટર વિઝન એન્જિન 50 લાખથી વધુ પાંદડાઓના નમૂનાઓ પર પ્રશિક્ષિત ડીપ ન્યુરલ નેટવર્ક દ્વારા સંચાલિત છે. જ્યારે તમે ફોટો અપલોડ કરો છો, ત્યારે મોડેલ 95% સચોટતા સાથે રોગને ઓળખે છે અને તાત્કાલિક જૈવિક તથા રાસાયણિક ઉપચાર સૂચવે છે.",
