    "faq_a3": "ચોક્કસ. અમારું એઆઈ પાક ભલામણ એન્જિન તમારી જમીન, સિંચાઈ અને બજેટ અનુસાર વધુ નફો આપતા પાકની ભલામણ કરે છે.",
