    "faq_desc": "ਖੇਤ ਏਆਈ ਦੇ ਕੰਪਿਊਟਰ ਵਿਜ਼ਨ, ਮੌਸਮ ਅਤੇ ਖੇਤੀਬਾੜੀ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਬਾਰੇ ਆਮ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਲੱਭੋ।",
    "faq_q1": "ਬਿਮਾਰੀ ਦੀ ਪਛਾਣ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ?",
    "faq_a1": "ਸਾਡਾ ਕੰਪਿਊਟਰ ਵਿਜ਼ਨ ਇੰਜਣ 50 ਲੱਖ ਤੋਂ ਵੱਧ ਪੱਤਿਆਂ ਦੇ ਨਮੂਨਿਆਂ ਤੇ ਸਿਖਲਾਈ ਪ੍ਰਾਪਤ ਡੀਪ ਨਿਊਰਲ ਨੈੱਟਵਰਕ ਦੁਆਰਾ ਚਲਾਇਆ ਜਾਂਦਾ ਹੈ। ਫੋਟੋ ਅੱਪਲੋਡ ਕਰਨ ਤੇ ਮਾਡਲ 95% ਸ਼ੁੱਧਤਾ ਨਾਲ ਬਿਮਾਰੀ ਦੀ ਪਛਾਣ ਕਰਦਾ ਹੈ ਅਤੇ ਜੈਵਿਕ ਤੇ ਰਸਾਇਣਕ ਇਲਾਜ ਦੱਸਦਾ ਹੈ।",
    "faq_q2": "ਕੀ ਮੌਸਮ ਡੇਟਾ ਅਸਲ-ਸਮੇਂ ਦਾ ਹੈ?",
    "faq_a2": "ਹਾਂ! ਖੇਤ ਏਆਈ ਇਸਰੋ (ISRO) ਅਤੇ ਸੈਟੇਲਾਈਟਾਂ ਤੋਂ 1 ਕਿਲੋਮੀਟਰ² ਦੇ ਡੋਪਲਰ ਰਾਡਾਰ ਸਟੇਸ਼ਨਾਂ ਰਾਹੀਂ ਅਸਲ-ਸਮੇਂ ਦਾ ਡੇਟਾ ਅੱਪਡੇਟ ਕਰਦਾ ਹੈ।",
    "faq_q3": "ਕੀ ਮੈਂ ਨਵੀਆਂ ਫਸਲਾਂ ਉਗਾ ਸਕਦਾ ਹਾਂ?",
    "faq_a3": "ਬਿਲਕੁਲ। ਸਾਡਾ ਏਆਈ ਫਸਲ ਸਿਫਾਰਸ਼ ਇੰਜਣ ਤੁਹਾਡੀ ਮਿੱਟੀ, ਪਾਣੀ ਅਤੇ ਬਜਟ ਦੇ ਆਧਾਰ ਤੇ ਵੱਧ ਮੁਨਾਫਾ ਦੇਣ ਵਾਲੀਆਂ ਫਸਲਾਂ ਦੀ ਸਿਫਾਰਸ਼ ਕਰਦਾ ਹੈ।",
    "faq_q4": "ਭਵਿੱਖਬਾਣੀਆਂ ਕਿੰਨੀਆਂ ਸਹੀ ਹਨ?",
    "faq_a4": "ਖੇਤੀਬਾੜੀ ਯੂਨੀਵਰਸਿਟੀਆਂ ਦੇ ਟੈਸਟਾਂ ਵਿੱਚ ਖੇਤ ਏਆਈ ਨੇ 100 ਤੋਂ ਵੱਧ ਫਸਲੀ ਬਿਮਾਰੀਆਂ ਵਿੱਚ 95.8% ਸ਼ੁੱਧਤਾ ਪ੍ਰਾਪਤ ਕੀਤੀ ਹੈ।",
    "faq_q5": "ਕੀ ਇਹ ਪਲੇਟਫਾਰਮ ਮੁਫਤ ਹੈ?",
    "faq_a5": "ਹਾਂ! ਬਿਮਾਰੀ ਜਾਂਚ, ਮੌਸਮ ਸਲਾਹ, ਫਸਲ ਗਾਈਡ ਅਤੇ ਮੰਡੀ ਭਾਅ ਕਿਸਾਨ ਵੀਰਾਂ ਲਈ ਬਿਲਕੁਲ ਮੁਫਤ ਹਨ।",
