    "hero_listen_title": "ਖੇਤ ਏਆਈ ਜਾਣ-ਪਛਾਣ",
    "hero_listen_text": "ਖੇਤ ਏਆਈ ਵਿੱਚ ਤੁਹਾਡਾ ਸੁਆਗਤ ਹੈ। ਨਵੀਂ ਪੀੜ੍ਹੀ ਦਾ ਸਮਾਰਟ ਖੇਤੀਬਾੜੀ ਪਲੇਟਫਾਰਮ। ਆਰਟੀਫਿਸ਼ੀਅਲ ਇੰਟੈਲੀਜੈਂਸ, ਫਸਲ ਪਛਾਣ ਅਤੇ ਸਰਕਾਰੀ ਸਬਸਿਡੀ ਗਾਈਡ।",
