    "weather_listen_text": "ਹਾਈਪਰਲੋਕਲ ਮੌਸਮ ਰਿਪੋਰਟ। ਅਸਲ-ਸਮੇਂ ਦਾ ਸੈਟੇਲਾਈਟ ਡੇਟਾ ਤਾਪਮਾਨ, ਮੀਂਹ ਦੀ ਸੰਭਾਵਨਾ ਅਤੇ ਛਿੜਕਾਅ ਸਲਾਹ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ।",
