    "about_badge": "ਖੇਤ ਏਆਈ ਬਾਰੇ",
    "about_title": "ਸਮਾਰਟ ਖੇਤੀ ਦੀ ਸ਼ੁਰੂਆਤ ਏਆਈ ਨਾਲ",
    "about_desc": "खेत एआई एक उन्नत कृषि मंच है जो किसानों को संपूर्ण फसल चक्र में सशक्त बनाता है। सही फसल के चयन से लेकर रोग निदान, मौसम निगरानी, उपज पूर्वानुमान और मंडी भाव तक, हमारा मंच वास्तविक समय की जानकारी प्रदान करता है।",
    "about_card1_title": "संपूर्ण जीवन चक्र सहायता",
