    "about_card2_title": "उपग्रह और ड्रोन एआई",
    "about_card2_desc": "उच्च-रिज़ॉल्यूशन मल्टी-स्पेक्ट्रल उपग्रह इमेजरी और माइक्रॉक्लाइमेट टेलीमेट्री सीधे आपके खेत से जुड़ी है।",
    "about_card3_title": "त्वरित रोग निदान",
