    "feat7_title": "एआई कृषि सहायक",
    "feat7_desc": "खेती से जुड़े कोई भी सवाल पूछें और अपनी स्थानीय भाषा में 24/7 तत्काल एआई उत्तर प्राप्त करें।",
    "feat7_btn": "कृषि विशेषज्ञ से बात करें",
    "feat8_title": "सरकारी योजनाएं और सब्सिडी",
    "feat8_desc": "सब्सिडी, फसल बीमा, सोलर पंप और कृषि सहायता योजनाओं की पात्रता तुरंत जांचें।",
