    "how_step2_badge": "चरण 02",
    "how_step2_title": "फसल का फोटो या विवरण अपलोड करें",
    "how_step2_desc": "प्रभावित पत्ती का फोटो खींचें, मिट्टी की एनपीके रिपोर्ट दर्ज करें या सेंसर सिंक करें।",
