    "faq_a2": "হ্যাঁ! খেত এআই ইসরো ও স্যাটেলাইটের মাধ্যমে প্রতি ১৫ মিনিটে রিয়েল-টাইম আবহাওয়া তথ্য আপডেট করে।",
    "faq_q3": "আমি কি নতুন ফসল চাষ করতে পারি?",
    "faq_a3": "অবশ্যই। আমাদের এআই ফসল সুপারিশ ইঞ্জিন আপনার মাটি ও সেচের উপর ভিত্তি করে লাভজনক বিকল্প ফসলের পরামর্শ দেয়।",
    "faq_q4": "ভবিষ্যদ্বাণী কতটা সঠিক?",
    "faq_a4": "কৃষি বিশ্ববিদ্যালয়গুলির পরীক্ষায় খেত এআই ১০০টিরও বেশি ফসলের রোগে ৯৫.৮% নির্ভুলতা অর্জন করেছে।",
    "faq_q5": "প্ল্যাটফর্মটি কি বিনামূল্যে ব্যবহারযোগ্য?",
    "faq_a5": "হ্যাঁ! রোগ নির্ণয়, আবহাওয়া পরামর্শ, ফসল গাইড এবং মান্ডি মূল্য কৃষকদের জন্য সম্পূর্ণ বিনামূল্যে।",
