    "faq_a1": "మా కంప్యూటర్ విజన్ ఇంజిన్ 50 లక్షలకు పైగా ఆకుల నమూనాలపై శిక్షణ పొందిన డీప్ న్యూరల్ నెట్‌వర్క్‌ల ద్వారా పనిచేస్తుంది. ఆకు ఫోటో అప్‌లోడ్ చేసినప్పుడు, ఇది 95% ఖచ్చితత్వంతో వ్యాధిని నిర్ధారించి సేంద్రీయ మరియు రసాయన చికిత్సలను సూచిస్తుంది.",
