    "why_title": "ఖేత్ ఏఐని ఎందుకు ఎంచుకోవాలి",
    "why_desc": "भारतीय किसानों की वास्तविक कृषि और बाजार चुनौतियों को हल करने के लिए विशेष रूप से निर्मित।",
    "why1_title": "एआई द्वारा संचालित",
    "why1_desc": "सटीक पौध रोग वर्गीकरण के लिए 50 लाख से अधिक पत्ती छवियों पर प्रशिक्षित डीप न्यूरल नेटवर्क।",
    "why2_title": "उपयोग में बेहद आसान",
    "why2_desc": "सभी किसान भाइयों के लिए सहज संचालन हेतु सरल और स्पष्ट इंटरफ़ेस।",
    "why3_title": "त्वरित भविष्यवाणी",
