    "test1_quote": "\"जब पिछले दिसंबर लुधियाना में हमारे गेहूं में पीला रतुआ लगा, तो खेत एआई ने फोटो खींचते ही 10 सेकंड में बता दिया। हमने तुरंत प्रोपिकोनाज़ोल का छिड़काव किया और अपनी पूरी 22 एकड़ फसल बचा ली। हमारी उपज 24% बढ़ गई!\"",
    "test1_author": "सरदार गुरप्रीत सिंह",
    "test1_loc": "गेहूं एवं धान किसान • लुधियाना, पंजाब",
    "test2_quote": "\"मंडी भाव की सुविधा कमाल की है। शुरुआती कटाई में बीटी कपास 6,800 रुपये में बेचने के बजाय, खेत एआई ने मुझे रुकने की सलाह दी। मैंने 3 सप्ताह बाद 7,550 रुपये प्रति क्विंटल पर बेचा, जिससे मुझे 14 एकड़ में 1.2 लाख रुपये का अतिरिक्त लाभ हुआ।\"",
    "test2_author": "रामेश्वर पाटिल",
    "test2_loc": "कपास एवं सोयाबीन उत्पादक • यवतमाल, महाराष्ट्र",
    "test3_quote": "\"स्मार्टफोन पर सीधे हिंदी में एआई सहायक से बात करने से मुझे अपने पॉलीहाउस टमाटरों के लिए सटीक एनपीके खाद की मात्रा जानने में मदद मिली। रासायनिक लागत 30% कम हो गई और टमाटर की गुणवत्ता निर्यात स्तर की हुई।\"",
    "test3_author": "श्रीमती सुनीता देवी",
