    "footer_desc": "कृत्रिम बुद्धिमत्ता द्वारा किसानों का सशक्तिकरण। आने वाले कल के लिए समृद्ध और स्मार्ट कृषि का निर्माण।",
    "footer_copyright": "© 2026 கேத் AI. அனைத்து உரிமைகளும் பாதுகாக்கப்பட்டவை.",
    "faq_badge": "அடிக்கடி கேட்கப்படும் கேள்விகள்",
    "faq_title": "நீங்கள் தெரிந்து கொள்ள வேண்டிய அனைத்தும்",
    "faq_desc": "கேத் ஏஐ (Khet AI) கணினி பார்வை, வானிலை மற்றும் விவசாய அம்சங்கள் குறித்த கேள்விகளுக்கான பதில்கள்.",
    "faq_q1": "நோய் கண்டறிதல் எவ்வாறு செயல்படுகிறது?",
    "faq_a1": "எங்கள் கணினி பார்வை என்ஜின் 50 லட்சத்திற்கும் அதிகமான இலை மாதிரிகளில் பயிற்சி பெற்ற டீப் நியூரல் நெட்வொர்க்குகள் மூலம் இயங்குகிறது. இலை புகைப்படத்தை பதிவேற்றினால், 95% துல்லியத்துடன் நோயை அடையாளம் கண்டு இயற்கை மற்றும் ரசாயன சிகிச்சை முறைகளை வழங்குகிறது.",
    "faq_q2": "வானிலை தரவு நிகழ்நேரமானதா?",
    "faq_a2": "ஆம்! கேத் ஏஐ இஸ்ரோ (ISRO) மற்றும் செயற்கைக்கோள்கள் மூலம் ஒவ்வொரு 15 நிமிடங்களுக்கும் நேரலை வானிலை தரவை புதுப்பிக்கிறது.",
    "faq_q3": "நான் புதிய பயிர்களை பயிரிட முடியுமா?",
    "faq_a3": "நிச்சயமாக. எங்கள் ஏஐ பயிர் பரிந்துரை என்ஜின் உங்கள் மண், நீர் மற்றும் பட்ஜெட்டின் அடிப்படையில் அதிக லாபம் தரும் மாற்றுப் பயிர்களை பரிந்துரைக்கிறது.",
    "faq_q4": "கணிப்புகள் எவ்வளவு துல்லியமானவை?",
    "faq_a4": "விவசாயப் பல்கலைக்கழக சோதனைகளில் கேத் ஏஐ 100+ பயிர் நோய்களில் 95.8% துல்லியத்தைப் பெற்றுள்ளது.",
    "faq_q5": "இந்த தளம் இலவசமானதா?",
    "faq_a5": "ஆம்! நோய் கண்டறிதல், வானிலை ஆலோசனை, பயிர் வழிகாட்டி மற்றும் சந்தை விலை விவசாயிகளுக்கு முற்றிலும் இலவசம்.",
    "disease_search_title": "பயிர் நோயை உள்ளிடவும் அல்லது பேசவும்:",
    "disease_input_placeholder": "நோயின் பெயரை தட்டச்சு செய்யவும் அல்லது பேசவும் (எ.கா. தக்காளி கருகல், கோதுமை துரு நோய்)...",
    "disease_dictate_btn": "பேசுக 🎤",
