    "disease_listening": "கேட்கிறது... பயிர் அல்லது நோயின் பெயரை பேசவும்",
    "hero_listen_title": "கேத் ஏஐ அறிமுகம்",
    "hero_listen_text": "கேத் ஏஐ-க்கு வரவேற்கிறோம். அடுத்த தலைமுறை காலநிலை ஸ்மார்ட் விவசாய தளம். பயிர் அடையாளம், நோய் கண்டறிதல் மற்றும் அரசு மானிய வழிகாட்டி.",
    "weather_listen_title": "வானிலை முன்னறிவிப்பு",
