    "test3_quote": "\"स्मार्टफोन पर सीधे हिंदी में एआई सहायक से बात करने से मुझे अपने पॉलीहाउस टमाटरों के लिए सटीक एनपीके खाद की मात्रा जानने में मदद मिली। रासायनिक लागत 30% कम हो गई और टमाटर की गुणवत्ता निर्यात स्तर की हुई।\"",
