    "faq_desc": "ಖೇತ್ ಎಐ (Khet AI) ಕಂಪ್ಯೂಟರ್ ವಿಷನ್, ಹವಾಮಾನ ಮತ್ತು ಕೃಷಿ ವೈಶಿಷ್ಟ್ಯಗಳ ಬಗ್ಗೆ ಸಾಮಾನ್ಯ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಗಳನ್ನು ಪಡೆಯಿರಿ.",
    "faq_q1": "ರೋಗ ಪತ್ತೆ ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ?",
    "faq_a1": "ನಮ್ಮ ಕಂಪ್ಯೂಟರ್ ವಿಷನ್ ಎಂಜಿನ್ 50 ಲಕ್ಷಕ್ಕೂ ಹೆಚ್ಚು ಎಲೆಗಳ ಮಾದರಿಗಳಲ್ಲಿ ತರಬೇತಿ ಪಡೆದ ಡೀಪ್ ನ್ಯೂರಾಲ್ ನೆಟ್‌ವರ್ಕ್‌ಗಳ ಮೂಲಕ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ. ಎಲೆಯ ಫೋಟೋ ಅಪ್‌ಲೋಡ್ ಮಾಡಿದಾಗ 95% ನಿಖರತೆಯೊಂದಿಗೆ ರೋಗ ಗುರುತಿಸಿ ಸಾವಯವ ಮತ್ತು ರಾಸಾಯನಿಕ ಚಿಕಿತ್ಸೆ ನೀಡುತ್ತದೆ.",
    "faq_q2": "ಹವಾಮಾನ ಡೇಟಾ ನೈಜ ಸಮಯದ್ದೇ?",
    "faq_a2": "ಹೌದು! ಖೇತ್ ಎಐ ಇಸ್ರೋ ಮತ್ತು ಉಪಗ್ರಹಗಳ ಮೂಲಕ ಪ್ರತಿ 15 ನಿಮಿಷಕ್ಕೆ ಲೈವ್ ಹವಾಮಾನವನ್ನು ನವೀಕರಿಸುತ್ತದೆ.",
    "faq_q3": "ನಾನು ಹೊಸ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದೇ?",
    "faq_a3": "ಖಂಡಿತವಾಗಿ. ನಮ್ಮ ಎಐ ಬೆಳೆ ಶಿಫಾರಸು ಎಂಜಿನ್ ನಿಮ್ಮ ಮಣ್ಣು, ನೀರು ಮತ್ತು ಬಜೆಟ್ ಆಧಾರದ ಮೇಲೆ ಹೆಚ್ಚಿನ ಲಾಭದಾಯಕ ಬೆಳೆಗಳನ್ನು ಶಿಫಾರಸು ಮಾಡುತ್ತದೆ.",
    "faq_q4": "ಮುನ್ಸೂಚನೆಗಳು ಎಷ್ಟು ನಿಖರವಾಗಿವೆ?",
    "faq_a4": "ಕೃಷಿ ವಿಶ್ವವಿದ್ಯಾಲಯಗಳ ಪರೀಕ್ಷೆಗಳಲ್ಲಿ ಖೇತ್ ಎಐ 100+ ಬೆಳೆ ರೋಗಗಳಲ್ಲಿ 95.8% ನಿಖರತೆಯನ್ನು ಸಾಧಿಸಿದೆ.",
    "faq_q5": "ಈ ವೇದಿಕೆ ಉಚಿತವೇ?",
