    "subsidy_listen_title": "ಸರ್ಕಾರಿ ಸಬ್ಸಿಡಿ ಪರೀಕ್ಷಕ",
    "subsidy_listen_text": "ಸರ್ಕಾರಿ ರೈತ ಸಬ್ಸಿಡಿ ಪರೀಕ್ಷಕ. ಸೋಲಾರ್ ಪಂಪ್, ಹನಿ ನೀರಾವರಿ, ಟ್ರ್ಯಾಕ್ಟರ್ ಮತ್ತು ಪಿಎಂ-ಕಿಸಾನ್ ಯೋಜನೆಗಳ ಮಾಹಿತಿ.",
