    "about_khet_p2": "मिट्टी-अनुकूल एनपीके सिफारिशें जो खाद की लागत 28% तक कम करती हैं",
    "about_khet_p3": "एआई मंडी भाव भविष्यवाणी जो पीक सीजन दरों पर बिक्री सुनिश्चित करती है",
    "features_badge": "ವೇದಿಕೆಯ ಪ್ರಮುಖ ಲಕ್ಷಣಗಳು",
    "features_title": "ರೈತರ ಪ್ರತಿಯೊಂದು ಅಗತ್ಯ, ಒಂದೇ ಆ್ಯಪ್‌ನಲ್ಲಿ",
    "features_desc": "अत्याधुनिक कंप्यूटर विज़न, डीप लर्निंग एल्गोरिदम और वास्तविक समय कृषि टेलीमेट्री, विशेष रूप से उच्च उपज के लिए तैयार।",
