    "feat5_desc": "लाइव मंडी भाव, साप्ताहिक मूल्य रुझान और संकटपूर्ण बिक्री से बचने के लिए एआई बिक्री सलाह देखें।",
    "feat5_btn": "मंडी भाव जांचें",
    "feat6_title": "स्मार्ट सिंचाई योजना",
    "feat6_desc": "बुद्धिमान सिंचाई योजना, वाष्पोत्सर्जन सूचकांक और नमी सेंसर स्वचालन द्वारा पानी का इष्टतम उपयोग करें।",
    "feat6_btn": "सिंचाई योजना",
    "feat7_title": "एआई कृषि सहायक",
    "feat7_desc": "खेती से जुड़े कोई भी सवाल पूछें और अपनी स्थानीय भाषा में 24/7 तत्काल एआई उत्तर प्राप्त करें।",
    "feat7_btn": "कृषि विशेषज्ञ से बात करें",
    "feat8_title": "सरकारी योजनाएं और सब्सिडी",
    "feat8_desc": "सब्सिडी, फसल बीमा, सोलर पंप और कृषि सहायता योजनाओं की पात्रता तुरंत जांचें।",
    "feat8_btn": "सब्सिडी पात्रता जांचें",
    "how_badge": "ಸರಳ 4 ಹಂತಗಳು",
    "how_title": "ಖೇತ್ ಎಐ ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ",
    "how_desc": "केवल चार आसान चरणों में कृषि डेटा को व्यावहारिक सिफारिशों में बदलें।",
