    "how_step3_title": "एआई डेटा का विश्लेषण करता है",
    "how_step3_desc": "डीप न्यूरल नेटवर्क पत्ती के रोग, उपग्रह रडार और जलवायु डेटा का विश्लेषण करते हैं।",
    "how_step4_badge": "चरण 04",
    "how_step4_title": "स्मार्ट सिफारिशें प्राप्त करें",
    "how_step4_desc": "तत्काल जैविक/रासायनिक नुस्खे, सिंचाई योजना और मंडी में सही समय पर बिक्री की सलाह पाएं।",
    "dash_badge": "लाइव इंटरएक्टिव एग्रीटेक सुइट",
    "dash_title": "खेत एआई डैशबोर्ड पूर्वावलोकन",
    "dash_desc": "हमारे लाइव कृषि इंजन का अनुभव करें। मौसम विश्लेषण, रोग स्कैनर, फसल सिफारिश और मंडी भाव रुझान का परीक्षण करें।",
    "why_badge": "ಖೇತ್ ಎಐ ಪ್ರಯೋಜನಗಳು",
    "why_title": "ಖೇತ್ ಎಐ ಏಕೆ ಆಯ್ಕೆ ಮಾಡಬೇಕು",
    "why_desc": "भारतीय किसानों की वास्तविक कृषि और बाजार चुनौतियों को हल करने के लिए विशेष रूप से निर्मित।",
    "why1_title": "एआई द्वारा संचालित",
    "why1_desc": "सटीक पौध रोग वर्गीकरण के लिए 50 लाख से अधिक पत्ती छवियों पर प्रशिक्षित डीप न्यूरल नेटवर्क।",
    "why2_title": "उपयोग में बेहद आसान",
    "why2_desc": "सभी किसान भाइयों के लिए सहज संचालन हेतु सरल और स्पष्ट इंटरफ़ेस।",
    "why3_title": "त्वरित भविष्यवाणी",
    "why3_desc": "लैब रिपोर्ट का इंतजार किए बिना सीधे अपने फोन पर सेकंडों में निदान पाएं।",
    "why4_title": "क्लाइमेट स्मार्ट",
    "why4_desc": "बेमौसम बारिश और गर्मी की लहरों से फसलों को बचाने के लिए सटीक पूर्वानुमान मॉडल।",
    "why5_title": "सतत कृषि को बढ़ावा",
    "why5_desc": "जैविक विकल्प, जैविक नियंत्रण और मिट्टी स्वास्थ्य संरक्षण को बढ़ावा देता है।",
    "why6_title": "बहुभाषी समर्थन",
    "why6_desc": "हिंदी, पंजाबी, मराठी, तेलुगु, गुजराती और अंग्रेजी सहित क्षेत्रीय आवाज़ मॉडल का समर्थन।",
    "why7_title": "सटीक मौसम पूर्वानुमान",
    "why7_desc": "वास्तविक समय मिट्टी नमी और पत्ती गीलापन सेंसर के साथ 1 वर्ग किमी डॉपलर रडार।",
    "why8_title": "स्मार्ट सिफारिशें",
    "why8_desc": "मिट्टी के एनपीके, मौसमी बाजार मांग और जल बजट को जोड़कर दी जाने वाली समग्र सलाह।",
    "test_badge": "ರೈತರ ಅನುಭವಗಳು",
    "test_title": "ದೇಶಾದ್ಯಂತ ರೈತರ ವಿಶ್ವಾಸ",
    "test_desc": "जानिए कैसे खेत एआई पंजाब से लेकर महाराष्ट्र तक के खेतों में वास्तविक आर्थिक लाभ पहुंचा रहा है।",
    "test1_quote": "\"जब पिछले दिसंबर लुधियाना में हमारे गेहूं में पीला रतुआ लगा, तो खेत एआई ने फोटो खींचते ही 10 सेकंड में बता दिया। हमने तुरंत प्रोपिकोनाज़ोल का छिड़काव किया और अपनी पूरी 22 एकड़ फसल बचा ली। हमारी उपज 24% बढ़ गई!\"",
    "test1_author": "सरदार गुरप्रीत सिंह",
    "test1_loc": "गेहूं एवं धान किसान • लुधियाना, पंजाब",
    "test2_quote": "\"मंडी भाव की सुविधा कमाल की है। शुरुआती कटाई में बीटी कपास 6,800 रुपये में बेचने के बजाय, खेत एआई ने मुझे रुकने की सलाह दी। मैंने 3 सप्ताह बाद 7,550 रुपये प्रति क्विंटल पर बेचा, जिससे मुझे 14 एकड़ में 1.2 लाख रुपये का अतिरिक्त लाभ हुआ।\"",
    "test2_author": "रामेश्वर पाटिल",
    "test2_loc": "कपास एवं सोयाबीन उत्पादक • यवतमाल, महाराष्ट्र",
    "test3_quote": "\"स्मार्टफोन पर सीधे हिंदी में एआई सहायक से बात करने से मुझे अपने पॉलीहाउस टमाटरों के लिए सटीक एनपीके खाद की मात्रा जानने में मदद मिली। रासायनिक लागत 30% कम हो गई और टमाटर की गुणवत्ता निर्यात स्तर की हुई।\"",
    "test3_author": "श्रीमती सुनीता देवी",
    "test3_loc": "सब्जी एवं बागवानी किसान • वाराणसी, उत्तर प्रदेश",
