    "faq_badge": "ବାରମ୍ବାର ପଚରାଯାଉଥିବା ପ୍ରଶ୍ନ",
    "faq_title": "ଆପଣ ଜାଣିବାକୁ ଥିବା ସମସ୍ତ ବିଷୟ",
    "faq_desc": "ଖେତ ଏଆଇ (Khet AI) ର କମ୍ପ୍ୟୁଟର ଭିଜନ, ପାଣିପାଗ ଏବଂ କୃଷି ସମ୍ବନ୍ଧୀୟ ପ୍ରଶ୍ନର ଉତ୍ତର ପାଆନ୍ତୁ।",
    "faq_q1": "ରୋଗ ଚିହ୍ନଟ କିପରି କାମ କରେ?",
    "faq_a1": "ଆମର କମ୍ପ୍ୟୁଟର ଭିଜନ ଇଞ୍ଜିନ ୫୦ ଲକ୍ଷରୁ ଅଧିକ ପତ୍ର ନମୁନାରେ ପ୍ରଶିକ୍ଷିତ ଡିପ୍ ନ୍ୟୁରାଲ ନେଟୱାର୍କ ଦ୍ୱାରା ପରିଚାଳିତ। ପତ୍ର ଫଟୋ ଅପଲୋଡ କଲେ ୯୫% ସଠିକତା ସହ ରୋଗ ଚିହ୍ନଟ କରି ଜୈବିକ ଓ ରାସାୟନିକ ପ୍ରତିକାର ପ୍ରଦାନ କରେ।",
    "faq_q2": "ପାଣିପାଗ ତଥ୍ୟ କଣ ପ୍ରକୃତ ସମୟର?",
    "faq_a2": "ହଁ! ଖେତ ଏଆଇ ଇସ୍ରୋ (ISRO) ଓ ସାଟେଲାଇଟ୍ ମାଧ୍ୟମରେ ପ୍ରତି ୧୫ ମିନିଟରେ ଲାଇଭ୍ ପାଣିପାଗ ଅପଡେଟ୍ କରେ।",
    "faq_q3": "ମୁଁ ନୂତନ ଫସଲ ଚାଷ କରିପାରିବି କି?",
    "faq_a3": "ନିଶ୍ଚିତ ଭାବରେ। ଆମର ଏଆଇ ଫସଲ ସୁପାରିଶ ଇଞ୍ଜିନ ଆପଣଙ୍କ ମାଟି ଓ ଜଳ ଅନୁଯାୟୀ ଲାଭଜନକ ବିକଳ୍ପ ଫସଲ ସୁପାରିଶ କରେ।",
    "faq_q4": "ଅନୁମାନ କେତେ ସଠିକ୍?",
    "faq_a4": "କୃଷି ବିଶ୍ୱବିଦ୍ୟାଳୟ ପରୀକ୍ଷଣରେ ଖେତ ଏଆଇ ୧୦୦+ ଫସଲ ରୋଗରେ ୯୫.୮% ସଠିକତା ହାସଲ କରିଛି।",
    "faq_q5": "ଏହି ପ୍ଲାଟଫର୍ମ କଣ ମାଗଣା?",
