      "organic": "Install 20 yellow sticky traps per acre; spray 5% Neem oil (5 ml/L) or fish oil rosin soap (25 g/L) against whitefly vectors.",
      "chemical": "Spray Afidopyropen 50 g/L DC (2 ml/L) or Diafenthiuron 50% WP (1.2 g/L) or Pyriproxyfen 10% EC (2 ml/L) for vector control.",
